css:
.ccd-ohlc-volume{--ccd-ov-up:#2BD67B;--ccd-ov-dn:#F0506E;--ccd-ov-ln:#1A2130;--ccd-ov-dim:#6B778C;--ccd-ov-tx:#D8DEE9;--ccd-ov-ac:#5B9DFF;--ccd-ov-e9:#5B9DFF;--ccd-ov-e21:#E7B35A;--ccd-ov-mono:ui-monospace,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;min-width:0;background:#0B0E15;border:1px solid var(--ccd-ov-ln);border-radius:6px;padding:7px 8px 6px;color:var(--ccd-ov-tx);font:10px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-variant-numeric:tabular-nums;outline:none}
.ccd-ohlc-volume *{box-sizing:border-box}
.ccd-ohlc-volume:focus-visible{box-shadow:0 0 0 1px var(--ccd-ov-ac)}
.ccd-ohlc-volume-hd{display:flex;flex-wrap:wrap;align-items:baseline;gap:1px 5px;min-width:0}
.ccd-ohlc-volume-sym{font-weight:700;font-size:11px;letter-spacing:.02em}
.ccd-ohlc-volume-tf{font-family:var(--ccd-ov-mono);font-size:8.5px;padding:0 3px;border:1px solid var(--ccd-ov-ln);border-radius:3px;color:#A9B4C6}
.ccd-ohlc-volume-desc{flex:1 1 118px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ccd-ov-dim);font-size:8.5px}
.ccd-ohlc-volume-last{margin-left:auto;display:flex;align-items:baseline;gap:4px;font-family:var(--ccd-ov-mono);white-space:nowrap}
.ccd-ohlc-volume-px{font-size:12px;font-weight:700;border-radius:2px;padding:0 2px}
.ccd-ohlc-volume-px.fu{animation:ccd-ohlc-volume-fu .5s ease-out}
.ccd-ohlc-volume-px.fd{animation:ccd-ohlc-volume-fd .5s ease-out}
.ccd-ohlc-volume-chg{font-style:normal;font-size:9px}
.ccd-ohlc-volume .up{color:var(--ccd-ov-up)}
.ccd-ohlc-volume .dn{color:var(--ccd-ov-dn)}
.ccd-ohlc-volume-leg{display:flex;flex-wrap:wrap;gap:0 7px;font-family:var(--ccd-ov-mono);font-size:8.5px;line-height:12px;color:var(--ccd-ov-dim);margin:4px 0 3px;min-height:24px}
.ccd-ohlc-volume-leg b{color:var(--ccd-ov-tx);font-weight:500}
.ccd-ohlc-volume-leg .e9 b{color:var(--ccd-ov-e9)}
.ccd-ohlc-volume-leg .e21 b{color:var(--ccd-ov-e21)}
.ccd-ohlc-volume-leg .ts{color:#A9B4C6}
.ccd-ohlc-volume-svg{display:block;width:100%;height:156px;touch-action:pan-y;cursor:crosshair}
.ccd-ohlc-volume-svg .gr{stroke:rgba(255,255,255,.055);stroke-width:1}
.ccd-ohlc-volume-svg .sep{stroke:var(--ccd-ov-ln);stroke-width:1}
.ccd-ohlc-volume-svg .ax{fill:var(--ccd-ov-dim);font:8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-ohlc-volume-svg .cu{fill:var(--ccd-ov-up);stroke:var(--ccd-ov-up)}
.ccd-ohlc-volume-svg .cd{fill:var(--ccd-ov-dn);stroke:var(--ccd-ov-dn)}
.ccd-ohlc-volume-svg .w{stroke-width:1;fill:none}
.ccd-ohlc-volume-svg .b{stroke-width:0}
.ccd-ohlc-volume-svg .v{fill-opacity:.36;stroke:none}
.ccd-ohlc-volume-svg .vma{fill:none;stroke:#A9B4C6;stroke-width:1;stroke-opacity:.6}
.ccd-ohlc-volume-svg .e9{fill:none;stroke:var(--ccd-ov-e9);stroke-width:1.2}
.ccd-ohlc-volume-svg .e21{fill:none;stroke:var(--ccd-ov-e21);stroke-width:1.2}
.ccd-ohlc-volume-svg .lp{stroke-width:1;stroke-dasharray:2 2;fill:none}
.ccd-ohlc-volume-svg .tagt{fill:#0B0E15;font:700 8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-ohlc-volume-svg .hl{fill:rgba(91,157,255,.10);stroke:rgba(91,157,255,.35);stroke-width:1}
.ccd-ohlc-volume-ft{display:flex;align-items:center;gap:8px;font-size:8.5px;color:var(--ccd-ov-dim);border-top:1px solid var(--ccd-ov-ln);padding-top:4px;margin-top:2px;white-space:nowrap}
.ccd-ohlc-volume-ft kbd{font:8px var(--ccd-ov-mono);border:1px solid var(--ccd-ov-ln);border-radius:2px;padding:0 2px;margin-right:1px;color:#A9B4C6}
.ccd-ohlc-volume-mode{margin-left:auto;font:700 8px var(--ccd-ov-mono);letter-spacing:.08em;color:var(--ccd-ov-tx);background:#121826;border:1px solid var(--ccd-ov-ln);border-radius:3px;padding:2px 6px;cursor:pointer}
.ccd-ohlc-volume-mode:hover{border-color:var(--ccd-ov-ac)}
.ccd-ohlc-volume-mode:focus-visible{outline:1px solid var(--ccd-ov-ac)}
@keyframes ccd-ohlc-volume-fu{from{background:rgba(43,214,123,.38)}to{background:transparent}}
@keyframes ccd-ohlc-volume-fd{from{background:rgba(240,80,110,.38)}to{background:transparent}}
@media (prefers-reduced-motion: reduce){
.ccd-ohlc-volume-px.fu,.ccd-ohlc-volume-px.fd{animation:none}
.ccd-ohlc-volume *{transition:none!important}
}

js:
var $ = function (s) { return root.querySelector(s); };
var svg = $('.ccd-ohlc-volume-svg'), leg = $('.ccd-ohlc-volume-leg');
var pxEl = $('.ccd-ohlc-volume-px'), chgEl = $('.ccd-ohlc-volume-chg'), modeBtn = $('.ccd-ohlc-volume-mode');
var TICK = 0.25, N = 84, END = 14 * 60 + 20; /* last bar opens 14:20 CT */
var seed = 918273;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 0, v = 0; while (!u) u = rnd(); while (!v) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }
function q(v) { return Math.round(v / TICK) * TICK; }
function fd(v, d) { return v.toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d }); }
function f2(v) { return fd(v, 2); }
function fi(v) { return Math.round(v).toLocaleString('en-US'); }
function hm(t) { return String(Math.floor(t / 60)).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0'); }
function r1(v) { return Math.round(v * 10) / 10; }
function nice(x) { var e = Math.pow(10, Math.floor(Math.log10(x))), f = x / e; return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * e; }
function kf(v) { return v >= 1000 ? (v / 1000).toFixed(1) + 'K' : String(Math.round(v)); }

/* 5-minute ES bars: quiet Globex before 08:30 CT, U-shaped RTH activity after. Every price sits on the 0.25 tick. */
var bars = [], p = 6729.5;
for (var i = 0; i < N; i++) {
  var t = END - (N - 1 - i) * 5, m = t - 510;
  var act = m >= 0 ? 1 + 1.5 * Math.exp(-m / 30) + 0.6 * Math.exp(-(390 - m) / 45) : 0.42;
  var s = Math.sqrt(act), o = q(p), c = q(o + gauss() * 2.6 * s + 0.05);
  var h = q(Math.max(o, c) + Math.abs(gauss()) * 1.3 * s), l = q(Math.min(o, c) - Math.abs(gauss()) * 1.3 * s);
  bars.push({ t: t, o: o, h: h, l: l, c: c, v: Math.round((3800 + rnd() * 2200) * act * (1 + Math.abs(c - o) / 8)) });
  p = c;
}
var SETTLE = q(bars[0].o - 6.5);

var e9 = [], e21 = [], vma = [];
function calc() {
  var a = bars[0].c, b = a;
  for (var i = 0; i < N; i++) {
    var x = bars[i];
    a = i ? a + (x.c - a) * 2 / 10 : x.c; b = i ? b + (x.c - b) * 2 / 22 : x.c;
    e9[i] = a; e21[i] = b;
    var sum = 0, n = 0;
    for (var j = Math.max(0, i - 19); j <= i; j++) { sum += bars[j].v; n++; }
    vma[i] = sum / n;
  }
}

var mode = 'candle', sel = null, lay = { off: 0, bw: 7, pw: 300 };
function render() {
  var W = Math.max(240, Math.round(svg.getBoundingClientRect().width) || 340), H = 156;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  var AX = 50, PW = W - AX, n = Math.min(N, Math.floor(PW / 7)), off = N - n, bw = PW / n, cw = Math.max(1, Math.min(9, bw * 0.62));
  lay = { off: off, bw: bw, pw: PW };
  var hi = -Infinity, lo = Infinity, vmax = 0, k;
  for (k = off; k < N; k++) {
    hi = Math.max(hi, bars[k].h, e9[k], e21[k]); lo = Math.min(lo, bars[k].l, e9[k], e21[k]); vmax = Math.max(vmax, bars[k].v);
  }
  var pad = (hi - lo) * 0.08; hi += pad; lo -= pad;
  var PT = 5, PB = 104, VT = 112, VB = 140;
  function Y(v) { return r1(PT + (hi - v) / (hi - lo) * (PB - PT)); }
  function X(i) { return r1((i + 0.5) * bw); }
  var out = '', st = nice((hi - lo) / 4), dec = st % 1 === 0 ? 0 : 2;
  for (k = Math.ceil(lo / st); k * st <= hi; k++) {
    var y = Y(k * st);
    out += '<line class="gr" x1="0" x2="' + PW + '" y1="' + y + '" y2="' + y + '"/><text class="ax" x="' + (PW + 4) + '" y="' + (y + 3) + '">' + fd(k * st, dec) + '</text>';
  }
  var iv = [15, 30, 60, 120].filter(function (x) { return x / 5 * bw >= 40; })[0] || 120;
  for (k = off; k < N; k++) {
    var tx = X(k - off);
    if (bars[k].t % iv === 0 && tx > 14 && tx < PW - 14) {
      out += '<line class="gr" x1="' + tx + '" x2="' + tx + '" y1="' + PT + '" y2="' + VB + '"/><text class="ax" x="' + tx + '" y="' + (H - 3) + '" text-anchor="middle">' + hm(bars[k].t) + '</text>';
    }
  }
  out += '<line class="sep" x1="0" x2="' + W + '" y1="' + (VT - 4) + '" y2="' + (VT - 4) + '"/><line class="sep" x1="' + PW + '" x2="' + PW + '" y1="0" y2="' + VB + '"/>';
  out += '<text class="ax" x="' + (PW + 4) + '" y="' + (VT + 6) + '">VOL</text><text class="ax" x="' + (PW + 4) + '" y="' + (VT + 16) + '">' + kf(vmax) + '</text><text class="ax" x="' + (PW + 4) + '" y="' + (H - 3) + '">CT</text>';
  if (sel !== null && sel >= off) {
    out += '<rect class="hl" x="' + r1((sel - off) * bw) + '" y="' + PT + '" width="' + r1(bw) + '" height="' + (VB - PT) + '"/>';
  }
  for (k = off; k < N; k++) {
    var b = bars[k], x = X(k - off), cl = b.c >= b.o ? 'cu' : 'cd', h2 = cw / 2;
    if (mode === 'candle') {
      var yo = Y(b.o), yc = Y(b.c), top = Math.min(yo, yc), bh = Math.max(1, r1(Math.abs(yc - yo)));
      out += '<line class="w ' + cl + '" x1="' + x + '" x2="' + x + '" y1="' + Y(b.h) + '" y2="' + Y(b.l) + '"/><rect class="b ' + cl + '" x="' + r1(x - h2) + '" y="' + top + '" width="' + r1(cw) + '" height="' + bh + '"/>';
    } else {
      out += '<path class="w ' + cl + '" d="M' + x + ' ' + Y(b.h) + 'V' + Y(b.l) + 'M' + r1(x - h2) + ' ' + Y(b.o) + 'H' + x + 'M' + x + ' ' + Y(b.c) + 'H' + r1(x + h2) + '"/>';
    }
    var vh = r1(b.v / vmax * (VB - VT));
    out += '<rect class="v ' + cl + '" x="' + r1(x - h2) + '" y="' + r1(VB - vh) + '" width="' + r1(cw) + '" height="' + vh + '"/>';
  }
  var p9 = [], p21 = [], pv = [];
  for (k = off; k < N; k++) {
    var xx = X(k - off);
    p9.push(xx + ',' + Y(e9[k])); p21.push(xx + ',' + Y(e21[k])); pv.push(xx + ',' + r1(VB - vma[k] / vmax * (VB - VT)));
  }
  out += '<polyline class="e21" points="' + p21.join(' ') + '"/><polyline class="e9" points="' + p9.join(' ') + '"/><polyline class="vma" points="' + pv.join(' ') + '"/>';
  var L = bars[N - 1], ly = Y(L.c), lc = L.c >= L.o ? 'cu' : 'cd';
  out += '<line class="lp ' + lc + '" x1="0" x2="' + PW + '" y1="' + ly + '" y2="' + ly + '"/><rect class="' + lc + '" x="' + (PW + 1) + '" y="' + (ly - 6.5) + '" width="' + (AX - 2) + '" height="13" rx="2"/><text class="tagt" x="' + (PW + 4) + '" y="' + (ly + 3) + '">' + f2(L.c) + '</text>';
  svg.innerHTML = out;
}

function legend() {
  var i = sel === null ? N - 1 : sel, b = bars[i], d = b.c - b.o, up = d >= 0, cl = up ? 'up' : 'dn';
  leg.innerHTML = '<span class="ts">' + hm(b.t) + ' CT' + (sel === null ? ' · forming' : '') + '</span>' +
    '<span>O <b>' + f2(b.o) + '</b></span><span>H <b>' + f2(b.h) + '</b></span><span>L <b>' + f2(b.l) + '</b></span>' +
    '<span>C <b class="' + (d ? cl : '') + '">' + f2(b.c) + '</b></span><span class="' + (d ? cl : '') + '">' + (d > 0 ? '▲ +' : d < 0 ? '▼ −' : '◆ ') + f2(Math.abs(d)) + '</span>' +
    '<span class="e9">EMA9 <b>' + f2(e9[i]) + '</b></span><span class="e21">EMA21 <b>' + f2(e21[i]) + '</b></span>' +
    '<span>VOL <b>' + fi(b.v) + '</b></span><span>VMA20 <b>' + fi(vma[i]) + '</b></span><span>STL <b>' + f2(SETTLE) + '</b></span>';
}

function head() {
  var L = bars[N - 1], d = L.c - SETTLE, up = d >= 0, pc = d / SETTLE * 100;
  pxEl.textContent = f2(L.c);
  chgEl.textContent = (up ? '▲ +' : '▼ −') + f2(Math.abs(d)) + ' (' + (up ? '+' : '−') + Math.abs(pc).toFixed(2) + '%)';
  chgEl.className = 'ccd-ohlc-volume-chg ' + (up ? 'up' : 'dn');
}

function all() { calc(); render(); legend(); head(); }
all();

function setMode(m) { mode = m; modeBtn.textContent = m === 'candle' ? 'CANDLE' : 'OHLC BAR'; render(); }
modeBtn.addEventListener('click', function () { setMode(mode === 'candle' ? 'bar' : 'candle'); });

root.addEventListener('keydown', function (e) {
  var i = sel === null ? N - 1 : sel, k = e.key;
  if (k === 'ArrowLeft') sel = Math.max(lay.off, i - 1);
  else if (k === 'ArrowRight') sel = i + 1 >= N ? null : i + 1;
  else if (k === 'Home') sel = lay.off;
  else if (k === 'End' || k === 'Escape') sel = null;
  else if (k === 'b' || k === 'B') { setMode(mode === 'candle' ? 'bar' : 'candle'); e.preventDefault(); return; }
  else return;
  e.preventDefault(); render(); legend();
});
svg.addEventListener('pointermove', function (e) {
  var r = svg.getBoundingClientRect(), x = (e.clientX - r.left) * (parseFloat(svg.getAttribute('viewBox').split(' ')[2]) / r.width);
  if (x > lay.pw) return;
  var i = Math.min(N - 1, lay.off + Math.max(0, Math.floor(x / lay.bw)));
  if (i !== sel) { sel = i; render(); legend(); }
});
svg.addEventListener('pointerleave', function () { sel = null; render(); legend(); });

/* live forming bar: last price walks on the tick grid, high/low and volume follow */
var timer = setInterval(function () {
  if (!root.isConnected) return clearInterval(timer);
  var b = bars[N - 1], step = (rnd() < 0.5 ? -1 : 1) * TICK * (rnd() < 0.8 ? 1 : 2);
  b.c = q(b.c + step); if (b.c > b.h) b.h = b.c; if (b.c < b.l) b.l = b.c;
  b.v += 3 + Math.floor(rnd() * 45);
  all();
  pxEl.classList.remove('fu', 'fd'); void pxEl.offsetWidth; pxEl.classList.add(step > 0 ? 'fu' : 'fd');
}, 1400);

if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () { if (!root.isConnected) return ro.disconnect(); render(); });
  ro.observe(svg);
}

