function sessions(n) {
  var d = new Date(Date.UTC(2026, 8, 23)), out = [];
  while (out.length < n) {
    var w = d.getUTCDay();
    if (w > 0 && w < 6 && !HOL[d.toISOString().slice(0, 10)]) out.unshift(new Date(d.getTime()));
    d.setUTCDate(d.getUTCDate() - 1);
  }
