}
var N = 72, days = sessions(N), bars = [], pc = 497.84;
for (var i = 0; i < N; i++) {
  /* overnight gap and intraday move drawn separately: that is what makes hollow-red and filled-green bars appear */
  var o = r2(pc * (1 + gauss() * 0.0075));
  var c = r2(o * (1 + gauss() * 0.0095 + 0.0004));
  var h = r2(Math.max(o, c) * (1 + Math.abs(gauss()) * 0.0042));
  var l = r2(Math.min(o, c) * (1 - Math.abs(gauss()) * 0.0042));
