function klass(b) { var up = b.c >= b.p, hol = b.c > b.o; return up ? (hol ? 0 : 1) : (hol ? 2 : 3); }
var NAMES = ['Hollow ▲', 'Filled ▲', 'Hollow ▼', 'Filled ▼'];
