var sel = null, iso = null, lay = { off: 0, bw: 8, pw: 300 };
function render() {
  var W = Math.max(240, Math.round(svg.getBoundingClientRect().width) || 340), H = 146;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  var AX = 44, PW = W - AX, n = Math.min(N, Math.floor(PW / 8)), off = N - n, bw = PW / n, cw = Math.max(3, Math.min(9, Math.round(bw * 0.62)));
