css:
.ccd-heikin-ashi{--ccd-ha-up:#2BD67B;--ccd-ha-dn:#F0506E;--ccd-ha-ln:#1A2130;--ccd-ha-dim:#6B778C;--ccd-ha-tx:#D8DEE9;--ccd-ha-ac:#5B9DFF;--ccd-ha-bg:#0B0E15;--ccd-ha-mono:ui-monospace,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;min-width:0;background:var(--ccd-ha-bg);border:1px solid var(--ccd-ha-ln);border-radius:6px;padding:7px 8px 6px;color:var(--ccd-ha-tx);font:10px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-variant-numeric:tabular-nums;outline:none}
.ccd-heikin-ashi *{box-sizing:border-box}
.ccd-heikin-ashi:focus-visible{box-shadow:0 0 0 1px var(--ccd-ha-ac)}
.ccd-heikin-ashi-hd{display:flex;align-items:center;gap:5px;min-width:0}
.ccd-heikin-ashi-sym{font-weight:700;font-size:11px;letter-spacing:.02em}
.ccd-heikin-ashi-tf{font-family:var(--ccd-ha-mono);font-size:8.5px;padding:0 3px;border:1px solid var(--ccd-ha-ln);border-radius:3px;color:#A9B4C6}
.ccd-heikin-ashi-desc{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ccd-ha-dim);font-size:8.5px}
.ccd-heikin-ashi-seg{display:inline-flex;border:1px solid var(--ccd-ha-ln);border-radius:3px;overflow:hidden;flex:none}
.ccd-heikin-ashi-seg button{font:700 8px var(--ccd-ha-mono);letter-spacing:.06em;color:var(--ccd-ha-dim);background:transparent;border:0;padding:2px 6px;cursor:pointer}
.ccd-heikin-ashi-seg button[aria-pressed="true"]{background:#1A2438;color:var(--ccd-ha-tx)}
.ccd-heikin-ashi-seg button:focus-visible{outline:1px solid var(--ccd-ha-ac);outline-offset:-1px}
.ccd-heikin-ashi-px{display:flex;flex-wrap:wrap;align-items:baseline;gap:0 6px;font-family:var(--ccd-ha-mono);font-size:8.5px;color:var(--ccd-ha-dim);margin:3px 0 2px}
.ccd-heikin-ashi-px b{font-size:12px;color:var(--ccd-ha-tx)}
.ccd-heikin-ashi .up{color:var(--ccd-ha-up)}
.ccd-heikin-ashi .dn{color:var(--ccd-ha-dn)}
.ccd-heikin-ashi-svg{display:block;width:100%;height:132px;touch-action:pan-y;cursor:crosshair}
.ccd-heikin-ashi-svg .gr{stroke:rgba(255,255,255,.055);stroke-width:1}
.ccd-heikin-ashi-svg .sep{stroke:var(--ccd-ha-ln);stroke-width:1}
.ccd-heikin-ashi-svg .wk{stroke:#3A4558;stroke-width:1;stroke-dasharray:3 2}
.ccd-heikin-ashi-svg .ax{fill:var(--ccd-ha-dim);font:8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-heikin-ashi-svg .wkt{fill:#56627A;font:7.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-heikin-ashi-svg .cu{fill:var(--ccd-ha-up);stroke:var(--ccd-ha-up)}
.ccd-heikin-ashi-svg .cd{fill:var(--ccd-ha-dn);stroke:var(--ccd-ha-dn)}
.ccd-heikin-ashi-svg .w{stroke-width:1;fill:none}
.ccd-heikin-ashi-svg .b{stroke-width:0}
.ccd-heikin-ashi-svg .rc{fill:#E8EDF6;stroke:var(--ccd-ha-bg);stroke-width:.8}
.ccd-heikin-ashi-svg .hl{fill:rgba(91,157,255,.10);stroke:rgba(91,157,255,.35);stroke-width:1}
.ccd-heikin-ashi-svg .lp{stroke-width:1;stroke-dasharray:2 2;fill:none}
.ccd-heikin-ashi-svg .tagt{fill:var(--ccd-ha-bg);font:700 8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-heikin-ashi-low{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:5px 10px;margin-top:4px;padding-top:4px;border-top:1px solid var(--ccd-ha-ln)}
.ccd-heikin-ashi-cmp{width:100%;border-collapse:collapse;font:8.5px/1.25 var(--ccd-ha-mono)}
.ccd-heikin-ashi-cmp th{font-weight:600;font-size:7.5px;letter-spacing:.08em;color:var(--ccd-ha-dim);text-align:right;padding:0 0 2px 4px;border-bottom:1px solid var(--ccd-ha-ln)}
.ccd-heikin-ashi-cmp th.ccd-heikin-ashi-ts{text-align:left;padding-left:0;letter-spacing:0;color:#A9B4C6;white-space:nowrap}
.ccd-heikin-ashi-cmp td{text-align:right;padding:1px 0 0 4px;color:var(--ccd-ha-tx);white-space:nowrap}
.ccd-heikin-ashi-cmp td:first-child{text-align:left;padding-left:0;color:var(--ccd-ha-dim)}
.ccd-heikin-ashi-cmp td.d{color:var(--ccd-ha-dim)}
.ccd-heikin-ashi-trend{display:flex;flex-direction:column;gap:2px;min-width:0}
.ccd-heikin-ashi-run{font:700 9px var(--ccd-ha-mono);letter-spacing:.04em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccd-heikin-ashi-kv{display:flex;justify-content:space-between;gap:4px;font-size:8px;color:var(--ccd-ha-dim);white-space:nowrap}
.ccd-heikin-ashi-kv b{font:600 8.5px var(--ccd-ha-mono);color:var(--ccd-ha-tx)}
.ccd-heikin-ashi-strip{display:grid;grid-template-columns:repeat(24,1fr);gap:1px;margin-top:2px;height:9px}
.ccd-heikin-ashi-strip i{display:block;border-radius:1px;border:1px solid transparent}
.ccd-heikin-ashi-strip i.su{background:var(--ccd-ha-up)}
.ccd-heikin-ashi-strip i.sd{background:var(--ccd-ha-dn)}
.ccd-heikin-ashi-strip i.wu{border-color:var(--ccd-ha-up);opacity:.75}
.ccd-heikin-ashi-strip i.wd{border-color:var(--ccd-ha-dn);opacity:.75}
.ccd-heikin-ashi-strip i.cur{box-shadow:0 0 0 1px var(--ccd-ha-ac)}
.ccd-heikin-ashi-ft{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;font-size:8.5px;color:var(--ccd-ha-dim);border-top:1px solid var(--ccd-ha-ln);padding-top:4px;margin-top:4px}
.ccd-heikin-ashi-ft kbd{font:8px var(--ccd-ha-mono);border:1px solid var(--ccd-ha-ln);border-radius:2px;padding:0 2px;color:#A9B4C6}
.ccd-heikin-ashi-fx{font:7.5px var(--ccd-ha-mono);color:#56627A;margin-left:auto}
@media (prefers-reduced-motion: reduce){
.ccd-heikin-ashi *{transition:none!important;animation:none!important}
}

