  if (sel !== null && sel >= off) out += '<rect class="hl" x="' + r1((sel - off) * bw) + '" y="' + PT + '" width="' + r1(bw) + '" height="' + (PB - PT) + '"/>';
  for (k = off; k < N; k++) {
