css:
.ccd-range-area{--ccd-ra-up:#2BD67B;--ccd-ra-dn:#F0506E;--ccd-ra-ln:#1A2130;--ccd-ra-dim:#6B778C;--ccd-ra-tx:#D8DEE9;--ccd-ra-ac:#5B9DFF;--ccd-ra-bg:#0B0E15;--ccd-ra-mono:ui-monospace,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;min-width:0;background:var(--ccd-ra-bg);border:1px solid var(--ccd-ra-ln);border-radius:6px;padding:7px 8px 6px;color:var(--ccd-ra-tx);font:10px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-variant-numeric:tabular-nums;outline:none}
.ccd-range-area *{box-sizing:border-box}
.ccd-range-area:focus-visible{box-shadow:0 0 0 1px var(--ccd-ra-ac)}
.ccd-range-area-hd{display:flex;flex-wrap:wrap;align-items:baseline;gap:1px 5px;min-width:0}
.ccd-range-area-sym{font-weight:700;font-size:11px;letter-spacing:.02em}
.ccd-range-area-tf{font-family:var(--ccd-ra-mono);font-size:8.5px;padding:0 3px;border:1px solid var(--ccd-ra-ln);border-radius:3px;color:#A9B4C6;white-space:nowrap}
.ccd-range-area-desc{flex:1 1 60px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ccd-ra-dim);font-size:8.5px}
.ccd-range-area-last{margin-left:auto;display:flex;align-items:baseline;gap:4px;font-family:var(--ccd-ra-mono);white-space:nowrap}
.ccd-range-area-px{font-size:12px;font-weight:700}
.ccd-range-area-chg{font-style:normal;font-size:9px}
.ccd-range-area .up{color:var(--ccd-ra-up)}
.ccd-range-area .dn{color:var(--ccd-ra-dn)}
.ccd-range-area-bar{display:flex;flex-wrap:wrap;align-items:center;gap:3px 6px;margin:5px 0 4px;min-width:0}
.ccd-range-area-rng{display:inline-flex;border:1px solid var(--ccd-ra-ln);border-radius:3px;overflow:hidden;flex:none}
.ccd-range-area-rng button{font:700 8px var(--ccd-ra-mono);letter-spacing:.04em;color:var(--ccd-ra-dim);background:transparent;border:0;border-right:1px solid var(--ccd-ra-ln);padding:2px 5px;cursor:pointer;transition:background .15s,color .15s}
.ccd-range-area-rng button:last-child{border-right:0}
.ccd-range-area-rng button:hover{color:var(--ccd-ra-tx)}
.ccd-range-area-rng button[aria-pressed="true"]{background:#1A2A44;color:#CFE0FF}
.ccd-range-area-rng button:focus-visible{outline:1px solid var(--ccd-ra-ac);outline-offset:-1px}
.ccd-range-area-span{flex:1 1 auto;min-width:0;text-align:right;font:8.5px var(--ccd-ra-mono);color:var(--ccd-ra-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccd-range-area-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border:1px solid var(--ccd-ra-ln);border-radius:3px;margin-bottom:4px}
.ccd-range-area-stats div{display:flex;flex-direction:column;padding:2px 4px;border-right:1px solid var(--ccd-ra-ln);min-width:0}
.ccd-range-area-stats div:last-child{border-right:0}
.ccd-range-area-stats span{font-size:7px;letter-spacing:.1em;color:var(--ccd-ra-dim);white-space:nowrap}
.ccd-range-area-stats b{font:700 9.5px var(--ccd-ra-mono);text-align:right;white-space:nowrap}
.ccd-range-area-stats em{font:normal 7.5px var(--ccd-ra-mono);color:var(--ccd-ra-dim);text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccd-range-area-svg{display:block;width:100%;height:118px;touch-action:pan-y;cursor:crosshair}
.ccd-range-area-nav{display:block;width:100%;height:34px;margin-top:3px;touch-action:none;cursor:grab}
.ccd-range-area-nav.drag{cursor:grabbing}
.ccd-range-area-svg .gr,.ccd-range-area-nav .gr{stroke:rgba(255,255,255,.055);stroke-width:1}
.ccd-range-area-svg .sep{stroke:var(--ccd-ra-ln);stroke-width:1}
.ccd-range-area-svg .ax,.ccd-range-area-nav .ax{fill:var(--ccd-ra-dim);font:8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-range-area-svg .au{fill:var(--ccd-ra-up);fill-opacity:.17;stroke:none}
.ccd-range-area-svg .ad{fill:var(--ccd-ra-dn);fill-opacity:.17;stroke:none}
.ccd-range-area-svg .lu{fill:none;stroke:var(--ccd-ra-up);stroke-width:1.4;stroke-linejoin:round}
.ccd-range-area-svg .ld{fill:none;stroke:var(--ccd-ra-dn);stroke-width:1.4;stroke-linejoin:round}
.ccd-range-area-svg .bl{stroke:#8894A8;stroke-width:1;stroke-dasharray:3 3}
.ccd-range-area-svg .blt{fill:#0B0E15;font:700 8px ui-monospace,Menlo,Consolas,monospace}
.ccd-range-area-svg .blr{fill:#8894A8}
.ccd-range-area-svg .tu{fill:var(--ccd-ra-up)}
.ccd-range-area-svg .td{fill:var(--ccd-ra-dn)}
.ccd-range-area-svg .xh{stroke:#A9B4C6;stroke-width:1;stroke-dasharray:2 2}
.ccd-range-area-svg .dot{fill:var(--ccd-ra-bg);stroke:#E8EDF6;stroke-width:1.5}
.ccd-range-area-svg .tip{fill:#131A27;stroke:#2A3446;stroke-width:1}
.ccd-range-area-svg .tipt{fill:var(--ccd-ra-tx);font:8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-range-area-nav .na{fill:#5B6B85;fill-opacity:.28;stroke:#6F7F9A;stroke-width:.8}
.ccd-range-area-nav .sh{fill:#05070B;fill-opacity:.62}
.ccd-range-area-nav .win{fill:rgba(91,157,255,.08);stroke:var(--ccd-ra-ac);stroke-width:1}
.ccd-range-area-nav .hd{fill:var(--ccd-ra-ac)}
.ccd-range-area-nav .yr{stroke:#2A3446;stroke-width:1}
.ccd-range-area-ft{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;font-size:8.5px;color:var(--ccd-ra-dim);border-top:1px solid var(--ccd-ra-ln);padding-top:4px;margin-top:4px}
.ccd-range-area-ft kbd{font:8px var(--ccd-ra-mono);border:1px solid var(--ccd-ra-ln);border-radius:2px;padding:0 2px;color:#A9B4C6}
@media (prefers-reduced-motion: reduce){
.ccd-range-area-rng button{transition:none}
.ccd-range-area *{transition:none!important;animation:none!important}
}

