var $ = function (s) { return root.querySelector(s); };
var svg = $('.ccd-range-area-svg'), nav = $('.ccd-range-area-nav'), spanEl = $('.ccd-range-area-span');
var btns = [].slice.call(root.querySelectorAll('.ccd-range-area-rng button'));
var E = {}; ['px', 'chg', 'ret', 'abs', 'hi', 'hid', 'lo', 'lod', 'dd', 'ddd', 'vol', 'n'].forEach(function (k) { E[k] = $('.ccd-range-area-' + k); });
