    var y = Y(k * st);
    out += '<line class="gr" x1="0" x2="' + PW + '" y1="' + y + '" y2="' + y + '"/><text class="ax" x="' + (PW + 4) + '" y="' + (y + 3) + '">' + (k * st).toFixed(st < 1 ? 1 : 0) + '</text>';
