  out += '<defs><clipPath id="' + uid + 'a"><rect x="0" y="0" width="' + PW + '" height="' + yb + '"/></clipPath><clipPath id="' + uid + 'b"><rect x="0" y="' + yb + '" width="' + PW + '" height="' + (H - yb) + '"/></clipPath></defs>';
  out += '<path class="au" clip-path="url(#' + uid + 'a)" d="' + area + '"/><path class="ad" clip-path="url(#' + uid + 'b)" d="' + area + '"/>';
  out += '<path class="lu" clip-path="url(#' + uid + 'a)" d="' + line + '"/><path class="ld" clip-path="url(#' + uid + 'b)" d="' + line + '"/>';
  out += '<line class="bl" x1="0" x2="' + PW + '" y1="' + yb + '" y2="' + yb + '"/>';
  out += '<line class="sep" x1="' + PW + '" x2="' + PW + '" y1="0" y2="' + PB + '"/><line class="sep" x1="0" x2="' + W + '" y1="' + PB + '" y2="' + PB + '"/>';
  var ly = Y(px[i1]), lu = px[i1] >= base;
  out += '<rect class="blr" x="' + (PW + 1) + '" y="' + (yb - 6) + '" width="' + (AX - 2) + '" height="12" rx="2"/><text class="blt" x="' + (PW + 4) + '" y="' + (yb + 3) + '">' + f2(base) + '</text>';
  out += '<rect class="' + (lu ? 'tu' : 'td') + '" x="' + (PW + 1) + '" y="' + (ly - 6) + '" width="' + (AX - 2) + '" height="12" rx="2"/><text class="blt" x="' + (PW + 4) + '" y="' + (ly + 3) + '">' + f2(px[i1]) + '</text>';
  if (hov !== null && hov >= i0 && hov <= i1) {
    var hx = X(hov), hy = Y(px[hov]), rr = px[hov] / base - 1;
    var txt = dfmt(dates[hov]) + '  ' + f2(px[hov]) + '  ' + sgn(rr * 100, 2) + '%';
    var tw = txt.length * 5.2 + 10, tX = Math.max(0, Math.min(PW - tw, hx - tw / 2));
    out += '<line class="xh" x1="' + hx + '" x2="' + hx + '" y1="' + PT + '" y2="' + PB + '"/><circle class="dot" cx="' + hx + '" cy="' + hy + '" r="3"/>';
    out += '<rect class="tip" x="' + r1(tX) + '" y="1" width="' + r1(tw) + '" height="13" rx="2"/><text class="tipt" x="' + r1(tX + 5) + '" y="10.5" xml:space="preserve">' + txt + '</text>';
  } else {
    out += '<text class="ax" x="2" y="10">base = close ' + dfmt(dates[i0]) + ' · fill vs base</text>';
  }
  svg.innerHTML = out;
  renderNav();
}
function renderNav() {
  var W = Math.max(240, Math.round(nav.getBoundingClientRect().width) || 340), H = 34;
  nav.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  navLay.w = W;
  var hi = Math.max.apply(null, px), lo = Math.min.apply(null, px), k;
  function X(k) { return r1(k / (N - 1) * (W - 2) + 1); }
  function Y(v) { return r1(3 + (hi - v) / (hi - lo) * (H - 6)); }
  var out = '', d = 'M' + X(0) + ' ' + (H - 1);
  for (k = 0; k < N; k++) d += 'L' + X(k) + ' ' + Y(px[k]);
  d += 'L' + X(N - 1) + ' ' + (H - 1) + 'Z';
  for (k = 1; k < N; k++) if (dates[k].getUTCFullYear() !== dates[k - 1].getUTCFullYear()) {
    out += '<line class="yr" x1="' + X(k) + '" x2="' + X(k) + '" y1="0" y2="' + H + '"/><text class="ax" x="' + (X(k) + 3) + '" y="9">' + dates[k].getUTCFullYear() + '</text>';
  }
  out += '<path class="na" d="' + d + '"/>';
  var a = X(i0), b = X(i1);
  out += '<rect class="sh" x="0" y="0" width="' + a + '" height="' + H + '"/><rect class="sh" x="' + b + '" y="0" width="' + (W - b) + '" height="' + H + '"/>';
  out += '<rect class="win" x="' + a + '" y="0.5" width="' + r1(b - a) + '" height="' + (H - 1) + '"/>';
  out += '<rect class="hd" x="' + (a - 2) + '" y="' + (H / 2 - 7) + '" width="4" height="14" rx="1"/><rect class="hd" x="' + (b - 2) + '" y="' + (H / 2 - 7) + '" width="4" height="14" rx="1"/>';
  nav.innerHTML = out;
}
function head() {
  var d = px[N - 1] - px[N - 2], up = d >= 0;
  E.px.textContent = f2(px[N - 1]);
  E.chg.textContent = (up ? '▲ ' : '▼ ') + sgn(d, 2) + ' (' + sgn(d / px[N - 2] * 100, 2) + '%) 1D';
  E.chg.className = 'ccd-range-area-chg ' + (up ? 'up' : 'dn');
}
function setWin(a, b) {
  var w = Math.max(MINW, b - a);
  if (a < 0) { a = 0; } if (a + w > N - 1) a = N - 1 - w;
  i0 = Math.max(0, Math.round(a)); i1 = Math.min(N - 1, Math.round(a + w));
  stats(); render();
}
function preset(k) { i0 = PRESET[k](); i1 = N - 1; stats(); render(); }
head(); stats(); render();

btns.forEach(function (b) { b.addEventListener('click', function () { preset(b.getAttribute('data-r')); }); });
root.addEventListener('keydown', function (e) {
  var k = e.key, step = e.shiftKey ? 21 : 5;
  if (k >= '1' && k <= '6') preset(ORDER[+k - 1]);
  else if (k === 'ArrowLeft') setWin(i0 - step, i1 - step);
  else if (k === 'ArrowRight') setWin(i0 + step, i1 + step);
  else if (k === '[') { i0 = Math.max(0, i0 - step); stats(); render(); }
  else if (k === ']') { i0 = Math.min(i1 - MINW, i0 + step); stats(); render(); }
  else if (k === 'End') setWin(N - 1 - (i1 - i0), N - 1);
  else if (k === 'Home') setWin(0, i1 - i0);
  else return;
  e.preventDefault();
});
svg.addEventListener('pointermove', function (e) {
  var r = svg.getBoundingClientRect(), x = (e.clientX - r.left) * (parseFloat(svg.getAttribute('viewBox').split(' ')[2]) / r.width);
  var k = Math.round(i0 + Math.max(0, Math.min(1, (x - 1) / (lay.pw - 2))) * lay.n);
  if (k !== hov) { hov = k; render(); }
});
svg.addEventListener('pointerleave', function () { hov = null; render(); });
/* navigator: grab an edge to resize, the body to pan, empty track to recentre */
var drag = null;
function navIdx(e) { var r = nav.getBoundingClientRect(); return ((e.clientX - r.left) * (navLay.w / r.width) - 1) / (navLay.w - 2) * (N - 1); }
nav.addEventListener('pointerdown', function (e) {
  var k = navIdx(e), tol = 6 / navLay.w * N;
  if (Math.abs(k - i0) < tol) drag = { m: 'l' };
  else if (Math.abs(k - i1) < tol) drag = { m: 'r' };
  else if (k > i0 && k < i1) drag = { m: 'p', off: k - i0, w: i1 - i0 };
  else { var w0 = i1 - i0; setWin(k - w0 / 2, k + w0 / 2); drag = { m: 'p', off: w0 / 2, w: w0 }; }
  nav.setPointerCapture(e.pointerId); nav.classList.add('drag'); e.preventDefault();
});
nav.addEventListener('pointermove', function (e) {
  if (!drag) return;
  var k = navIdx(e);
  if (drag.m === 'l') { i0 = Math.max(0, Math.min(i1 - MINW, Math.round(k))); stats(); render(); }
  else if (drag.m === 'r') { i1 = Math.min(N - 1, Math.max(i0 + MINW, Math.round(k))); stats(); render(); }
  else setWin(k - drag.off, k - drag.off + drag.w);
});
function endDrag() { drag = null; nav.classList.remove('drag'); }
nav.addEventListener('pointerup', endDrag);
nav.addEventListener('pointercancel', endDrag);
if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () { if (!root.isConnected) return ro.disconnect(); render(); });
  ro.observe(svg);
}

css:
.ccd-crosshair{--ccd-xh-up:#2BD67B;--ccd-xh-dn:#F0506E;--ccd-xh-ln:#1A2130;--ccd-xh-dim:#6B778C;--ccd-xh-tx:#D8DEE9;--ccd-xh-ac:#5B9DFF;--ccd-xh-bg:#0B0E15;--ccd-xh-mono:ui-monospace,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;min-width:0;background:var(--ccd-xh-bg);border:1px solid var(--ccd-xh-ln);border-radius:6px;padding:7px 8px 6px;color:var(--ccd-xh-tx);font:10px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-variant-numeric:tabular-nums;outline:none}
.ccd-crosshair *{box-sizing:border-box}
.ccd-crosshair:focus-visible{box-shadow:0 0 0 1px var(--ccd-xh-ac)}
.ccd-crosshair-hd{display:flex;flex-wrap:wrap;align-items:baseline;gap:1px 5px;min-width:0;margin-bottom:4px}
.ccd-crosshair-sym{font-weight:700;font-size:11px;letter-spacing:.02em}
.ccd-crosshair-tf{font-family:var(--ccd-xh-mono);font-size:8.5px;padding:0 3px;border:1px solid var(--ccd-xh-ln);border-radius:3px;color:#A9B4C6}
.ccd-crosshair-desc{flex:1 1 90px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ccd-xh-dim);font-size:8.5px}
.ccd-crosshair-last{margin-left:auto;display:flex;align-items:baseline;gap:4px;font-family:var(--ccd-xh-mono);white-space:nowrap}
.ccd-crosshair-px{font-size:12px;font-weight:700}
.ccd-crosshair-chg{font-style:normal;font-size:9px}
.ccd-crosshair .up{color:var(--ccd-xh-up)}
.ccd-crosshair .dn{color:var(--ccd-xh-dn)}
.ccd-crosshair-plot{position:relative;display:flex;flex-direction:column}
.ccd-crosshair-svg{display:block;width:100%;height:178px;touch-action:pan-y;cursor:none}
.ccd-crosshair-svg .gr{stroke:rgba(255,255,255,.055);stroke-width:1}
.ccd-crosshair-svg .sep{stroke:var(--ccd-xh-ln);stroke-width:1}
.ccd-crosshair-svg .ax{fill:var(--ccd-xh-dim);font:8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-crosshair-svg .cu{fill:var(--ccd-xh-up);stroke:var(--ccd-xh-up)}
.ccd-crosshair-svg .cd{fill:var(--ccd-xh-dn);stroke:var(--ccd-xh-dn)}
.ccd-crosshair-svg .w{stroke-width:1;fill:none}
.ccd-crosshair-svg .b{stroke-width:0}
.ccd-crosshair-svg .v{fill-opacity:.22;stroke:none}
.ccd-crosshair-svg .lp{stroke-width:1;stroke-dasharray:2 2;fill:none;opacity:.7}
.ccd-crosshair-svg .col{fill:rgba(91,157,255,.07)}
.ccd-crosshair-svg .xl{stroke:#9AA7BD;stroke-width:1;stroke-dasharray:3 3}
.ccd-crosshair-svg .tg{fill:#2B4A7E;stroke:var(--ccd-xh-ac);stroke-width:1}
.ccd-crosshair-svg .tgt{fill:#EAF2FF;font:700 8.5px ui-monospace,Menlo,Consolas,monospace}
.ccd-crosshair-svg .snap{fill:none;stroke:#F2B84B;stroke-width:1.4}
.ccd-crosshair-svg .snt{fill:#F2B84B;font:700 8px ui-monospace,Menlo,Consolas,monospace}
.ccd-crosshair-dw{position:absolute;top:4px;width:112px;padding:4px 6px;background:rgba(13,18,28,.94);border:1px solid #243047;border-radius:3px;font:8.5px/1.34 var(--ccd-xh-mono);pointer-events:none;display:grid;grid-template-columns:auto 1fr;column-gap:6px;box-shadow:0 4px 14px rgba(0,0,0,.45)}
.ccd-crosshair-dw span{color:var(--ccd-xh-dim);white-space:nowrap}
.ccd-crosshair-dw b{font-weight:500;text-align:right;white-space:nowrap}
.ccd-crosshair-dw .t{grid-column:1 / -1;color:#A9B4C6;font-weight:700;border-bottom:1px solid #243047;margin-bottom:2px;padding-bottom:1px}
.ccd-crosshair-dw .cz{color:#9EC2FF}
.ccd-crosshair-dw .sn{color:#F2B84B}
.ccd-crosshair.ccd-crosshair-nar .ccd-crosshair-dw{position:static;order:-1;width:auto;grid-template-columns:auto 1fr auto 1fr;column-gap:8px;margin-bottom:3px;padding:3px 5px;box-shadow:none;background:#0E131D}
.ccd-crosshair.ccd-crosshair-nar .ccd-crosshair-dw .t{margin-bottom:1px}
.ccd-crosshair-ft{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;font-size:8.5px;color:var(--ccd-xh-dim);border-top:1px solid var(--ccd-xh-ln);padding-top:4px;margin-top:3px}
.ccd-crosshair-ft kbd{font:8px var(--ccd-xh-mono);border:1px solid var(--ccd-xh-ln);border-radius:2px;padding:0 2px;color:#A9B4C6}
.ccd-crosshair-mag{margin-left:auto;font:700 8px var(--ccd-xh-mono);letter-spacing:.06em;color:var(--ccd-xh-dim);background:#10151F;border:1px solid var(--ccd-xh-ln);border-radius:3px;padding:1px 5px;cursor:pointer;transition:color .15s,border-color .15s}
.ccd-crosshair-mag kbd{border-color:#2A3446}
.ccd-crosshair-mag[aria-pressed="true"]{color:#F2B84B;border-color:#7A5E27}
.ccd-crosshair-mag:focus-visible{outline:1px solid var(--ccd-xh-ac)}
@media (prefers-reduced-motion: reduce){
.ccd-crosshair-mag{transition:none}
.ccd-crosshair *{transition:none!important;animation:none!important}
}

js:
var $ = function (s) { return root.querySelector(s); };
var svg = $('.ccd-crosshair-svg'), gBars = $('.ccd-crosshair-bars'), gX = $('.ccd-crosshair-xh'), dw = $('.ccd-crosshair-dw');
var pxEl = $('.ccd-crosshair-px'), chgEl = $('.ccd-crosshair-chg'), magBtn = $('.ccd-crosshair-mag');
var TICK = 0.1, seed = 330917;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 0, v = 0; while (!u) u = rnd(); while (!v) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }
function q(v) { return Math.round(v / TICK) * TICK; }
function r1(v) { return Math.round(v * 10) / 10; }
function f1(v) { return v.toLocaleString('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 }); }
function sg(v) { return (v >= 0 ? '+' : '−') + f1(Math.abs(v)); }
function nice(x) { var e = Math.pow(10, Math.floor(Math.log10(x))), f = x / e; return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * e; }
var DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
function hm(d) { return String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); }

/* 15-minute COMEX bars on the ET clock, skipping the 17:00-18:00 maintenance halt */
var N = 96, times = [], t = new Date(Date.UTC(2026, 8, 23, 13, 45));
while (times.length < N) { if (t.getUTCHours() !== 17) times.unshift(new Date(t.getTime())); t = new Date(t.getTime() - 9e5); }
var bars = [], p = 3806.2;
for (var i = 0; i < N; i++) {
  var h = times[i].getUTCHours() + times[i].getUTCMinutes() / 60;
  var act = h >= 8.33 && h < 13.5 ? 2.2 : h >= 3 && h < 8.33 ? 1.3 : 0.6;
  var s = Math.sqrt(act), o = q(p), c = q(o + gauss() * 2.1 * s + 0.08);
  var hi = q(Math.max(o, c) + Math.abs(gauss()) * 1.1 * s), lo = q(Math.min(o, c) - Math.abs(gauss()) * 1.1 * s);
  bars.push({ t: times[i], o: o, h: hi, l: lo, c: c, v: Math.round((650 + rnd() * 500) * act * act * (1 + Math.abs(c - o) / 6)) });
  p = c;
}
var SETTLE = q(bars[0].o - 5.3), LAST = bars[N - 1];

var L = {}, st = { ix: N - 1, price: LAST.c, snap: 'C', live: false }, magnet = true;
function drawBars() {
  var W = Math.max(240, Math.round(svg.getBoundingClientRect().width) || 340), H = 178;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  var AX = 50, PW = W - AX, n = Math.min(N, Math.floor(PW / 6.5)), off = N - n, bw = PW / n, cw = Math.max(1.5, Math.min(8, bw * 0.62));
  var hi = -Infinity, lo = Infinity, vmax = 0, k;
  for (k = off; k < N; k++) { hi = Math.max(hi, bars[k].h); lo = Math.min(lo, bars[k].l); vmax = Math.max(vmax, bars[k].v); }
  var pad = (hi - lo) * 0.06; hi += pad; lo -= pad;
  var PT = 4, PB = H - 14;
  L = { W: W, H: H, AX: AX, PW: PW, off: off, bw: bw, hi: hi, lo: lo, PT: PT, PB: PB, nar: W < 320 };
  root.classList.toggle('ccd-crosshair-nar', L.nar);
  function Y(v) { return r1(PT + (hi - v) / (hi - lo) * (PB - PT)); }
  var out = '', stp = nice((hi - lo) / 5), dec = stp % 1 === 0 ? 0 : 1;
  for (k = Math.ceil(lo / stp); k * stp <= hi; k++) {
    var y = Y(k * stp);
    out += '<line class="gr" x1="0" x2="' + PW + '" y1="' + y + '" y2="' + y + '"/><text class="ax" x="' + (PW + 4) + '" y="' + (y + 3) + '">' + (k * stp).toLocaleString('en-US', { minimumFractionDigits: dec, maximumFractionDigits: dec }) + '</text>';
  }
  var iv = [60, 120, 180, 240].filter(function (m) { return m / 15 * bw >= 40; })[0] || 240;
  for (k = off; k < N; k++) {
    var mm = bars[k].t.getUTCHours() * 60 + bars[k].t.getUTCMinutes(), tx = r1((k - off + 0.5) * bw);
    if (mm % iv === 0 && tx > 14 && tx < PW - 14) out += '<line class="gr" x1="' + tx + '" x2="' + tx + '" y1="' + PT + '" y2="' + PB + '"/><text class="ax" x="' + tx + '" y="' + (H - 3) + '" text-anchor="middle">' + hm(bars[k].t) + '</text>';
  }
  out += '<line class="sep" x1="' + PW + '" x2="' + PW + '" y1="0" y2="' + PB + '"/><line class="sep" x1="0" x2="' + W + '" y1="' + PB + '" y2="' + PB + '"/>';
  for (k = off; k < N; k++) {
    var b = bars[k], x = r1((k - off + 0.5) * bw), cl = b.c >= b.o ? 'cu' : 'cd';
    var vh = r1(b.v / vmax * 26);
    out += '<rect class="v ' + cl + '" x="' + r1(x - cw / 2) + '" y="' + r1(PB - vh) + '" width="' + r1(cw) + '" height="' + vh + '"/>';
    var yo = Y(b.o), yc = Y(b.c);
    out += '<line class="w ' + cl + '" x1="' + x + '" x2="' + x + '" y1="' + Y(b.h) + '" y2="' + Y(b.l) + '"/><rect class="b ' + cl + '" x="' + r1(x - cw / 2) + '" y="' + Math.min(yo, yc) + '" width="' + r1(cw) + '" height="' + Math.max(1, r1(Math.abs(yc - yo))) + '"/>';
  }
  var ly = Y(LAST.c);
  out += '<line class="lp ' + (LAST.c >= SETTLE ? 'cu' : 'cd') + '" x1="0" x2="' + PW + '" y1="' + ly + '" y2="' + ly + '"/>';
  gBars.innerHTML = out;
  drawX();
}
function Y(v) { return r1(L.PT + (L.hi - v) / (L.hi - L.lo) * (L.PB - L.PT)); }
function invY(y) { return L.hi - (y - L.PT) / (L.PB - L.PT) * (L.hi - L.lo); }
function drawX() {
  var i = Math.max(L.off, st.ix), b = bars[i], x = r1((i - L.off + 0.5) * L.bw), y = Y(st.price), PW = L.PW, AX = L.AX, H = L.H;
  var out = '<rect class="col" x="' + r1((i - L.off) * L.bw) + '" y="' + L.PT + '" width="' + r1(L.bw) + '" height="' + (L.PB - L.PT) + '"/>';
  out += '<line class="xl" x1="' + x + '" x2="' + x + '" y1="' + L.PT + '" y2="' + L.PB + '"/>';
  if (y >= L.PT && y <= L.PB) {
    out += '<line class="xl" x1="0" x2="' + PW + '" y1="' + y + '" y2="' + y + '"/>';
    out += '<rect class="tg" x="' + (PW + 0.5) + '" y="' + (y - 7) + '" width="' + (AX - 1) + '" height="14" rx="2"/><text class="tgt" x="' + (PW + 4) + '" y="' + (y + 3) + '">' + f1(st.price) + '</text>';
    if (st.snap) out += '<circle class="snap" cx="' + x + '" cy="' + y + '" r="3.2"/><text class="snt" x="' + (x + 5) + '" y="' + (y - 4) + '">' + st.snap + '</text>';
  }
  var lab = DOW[b.t.getUTCDay()] + ' ' + hm(b.t), tw = lab.length * 5.3 + 8, tx = Math.max(0, Math.min(PW - tw, x - tw / 2));
  out += '<rect class="tg" x="' + r1(tx) + '" y="' + (L.PB + 1) + '" width="' + r1(tw) + '" height="' + (H - L.PB - 1) + '" rx="2"/><text class="tgt" x="' + r1(tx + tw / 2) + '" y="' + (H - 3.5) + '" text-anchor="middle">' + lab + '</text>';
  gX.innerHTML = out;
  var pv = i > 0 ? bars[i - 1].c : b.o, ch = b.c - pv, rng = b.h - b.l, dl = st.price - LAST.c, up = ch >= 0;
  dw.innerHTML = '<span class="t">' + DOW[b.t.getUTCDay()] + ' ' + hm(b.t) + ' ET' + (i === N - 1 ? ' · live' : '') + '</span>' +
    '<span>O</span><b>' + f1(b.o) + '</b><span>H</span><b>' + f1(b.h) + '</b><span>L</span><b>' + f1(b.l) + '</b>' +
    '<span>C</span><b class="' + (b.c >= b.o ? 'up' : 'dn') + '">' + f1(b.c) + '</b>' +
    '<span>Chg</span><b class="' + (up ? 'up' : 'dn') + '">' + (up ? '▲' : '▼') + sg(ch) + '</b>' +
    '<span>Chg%</span><b class="' + (up ? 'up' : 'dn') + '">' + (up ? '+' : '−') + Math.abs(ch / pv * 100).toFixed(3) + '%</b>' +
    '<span>Range</span><b>' + f1(rng) + ' · ' + Math.round(rng / TICK) + 't</b>' +
    '<span>Vol</span><b>' + b.v.toLocaleString('en-US') + '</b>' +
    '<span class="cz">Cursor</span><b class="' + (st.snap ? 'sn' : 'cz') + '">' + f1(st.price) + (st.snap ? ' ' + st.snap : '') + '</b>' +
    '<span>Δ last</span><b class="' + (dl >= 0 ? 'up' : 'dn') + '">' + sg(dl) + ' · ' + Math.round(dl / TICK) + 't</b>';
  var leftSide = x > PW / 2;
  dw.style.left = L.nar ? '' : leftSide ? '4px' : 'auto';
  dw.style.right = L.nar ? '' : leftSide ? 'auto' : (AX + 4) + 'px';
}
function snapTo(i, y) {
  var b = bars[i], best = null, bd = Infinity;
  [['O', b.o], ['H', b.h], ['L', b.l], ['C', b.c]].forEach(function (c) { var d = Math.abs(Y(c[1]) - y); if (d < bd) { bd = d; best = c; } });
  st.price = best[1]; st.snap = best[0];
}
function park() { st.ix = N - 1; st.price = LAST.c; st.snap = magnet ? 'C' : null; drawX(); }
function head() {
  var d = LAST.c - SETTLE, up = d >= 0;
  pxEl.textContent = f1(LAST.c);
  chgEl.textContent = (up ? '▲ ' : '▼ ') + sg(d) + ' (' + (up ? '+' : '−') + Math.abs(d / SETTLE * 100).toFixed(2) + '%) stl ' + f1(SETTLE);
  chgEl.className = 'ccd-crosshair-chg ' + (up ? 'up' : 'dn');
}
function setMag(on) { magnet = on; magBtn.setAttribute('aria-pressed', on ? 'true' : 'false'); if (on) snapTo(st.ix, Y(st.price)); else st.snap = null; drawX(); }
head(); drawBars(); setMag(true);

svg.addEventListener('pointermove', function (e) {
  var r = svg.getBoundingClientRect(), x = (e.clientX - r.left) * L.W / r.width, y = (e.clientY - r.top) * L.H / r.height;
  if (x > L.PW || y > L.PB) return;
  st.ix = Math.min(N - 1, L.off + Math.max(0, Math.floor(x / L.bw)));
  y = Math.max(L.PT, Math.min(L.PB, y));
  if (magnet) snapTo(st.ix, y); else { st.price = q(invY(y)); st.snap = null; }
  drawX();
});
svg.addEventListener('pointerleave', park);
magBtn.addEventListener('click', function () { setMag(!magnet); });
root.addEventListener('keydown', function (e) {
  var k = e.key, m = e.shiftKey ? 10 : 1;
  if (k === 'ArrowLeft' || k === 'ArrowRight') {
    st.ix = Math.max(L.off, Math.min(N - 1, st.ix + (k === 'ArrowLeft' ? -1 : 1)));
    if (magnet) snapTo(st.ix, Y(st.price));
    drawX();
  } else if (k === 'ArrowUp' || k === 'ArrowDown') {
    st.price = q(Math.max(L.lo, Math.min(L.hi, st.price + (k === 'ArrowUp' ? 1 : -1) * TICK * m)));
    if (magnet) setMag(false); else { st.snap = null; drawX(); }
  } else if (k === 'm' || k === 'M') setMag(!magnet);
  else if (k === 'Escape' || k === 'End') park();
  else if (k === 'Home') { st.ix = L.off; if (magnet) snapTo(st.ix, Y(st.price)); drawX(); }
  else return;
  e.preventDefault();
});
if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () { if (!root.isConnected) return ro.disconnect(); drawBars(); });
  ro.observe(svg);
}

css:
.ccd-mtf-strip{--ccd-mt-up:#2BD67B;--ccd-mt-dn:#F0506E;--ccd-mt-ln:#1A2130;--ccd-mt-dim:#6B778C;--ccd-mt-tx:#D8DEE9;--ccd-mt-ac:#5B9DFF;--ccd-mt-ema:#E7B35A;--ccd-mt-bg:#0B0E15;--ccd-mt-mono:ui-monospace,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;min-width:0;background:var(--ccd-mt-bg);border:1px solid var(--ccd-mt-ln);border-radius:6px;padding:7px 8px 6px;color:var(--ccd-mt-tx);font:10px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-variant-numeric:tabular-nums;outline:none}
