var $ = function (s) { return root.querySelector(s); };
var grid = $('.ccd-mtf-strip-grid'), sum = $('.ccd-mtf-strip-sum'), clk = $('.ccd-mtf-strip-clk');
var pxEl = $('.ccd-mtf-strip-px'), chgEl = $('.ccd-mtf-strip-chg');
var seed = 28;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 0, v = 0; while (!u) u = rnd(); while (!v) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }
function r2(v) { return Math.round(v * 100) / 100; }
function r1(v) { return Math.round(v * 10) / 10; }
function f2(v) { return v.toFixed(2); }
function sg(v, d) { return (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(d); }
function hm(m) { var t = 570 + m; return String(Math.floor(t / 60)).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0'); }

/* one 5-minute series, 20 Nasdaq sessions ending today at 14:30 ET; every other timeframe is aggregated from it */
var HOL = { '2026-09-07': 1 }, days = [], d0 = new Date(Date.UTC(2026, 8, 23));
while (days.length < 20) { var wd = d0.getUTCDay(); if (wd > 0 && wd < 6 && !HOL[d0.toISOString().slice(0, 10)]) days.unshift(new Date(d0.getTime())); d0.setUTCDate(d0.getUTCDate() - 1); }
var base = [], p = 171.3;
for (var d = 0; d < days.length; d++) {
  var last = d === days.length - 1 ? 300 : 385, dr = gauss() * 0.00022;
  if (d) p = r2(p * (1 + gauss() * 0.011));
  for (var m = 0; m <= last; m += 5) {
    var u = 1 + 1.4 * Math.exp(-m / 40) + 0.7 * Math.exp(-(390 - m) / 35), sd = 0.0024 * Math.sqrt(u);
    var o = r2(p), c = r2(o * (1 + dr + gauss() * sd));
    base.push({ d: d, m: m, o: o, h: r2(Math.max(o, c) * (1 + Math.abs(gauss()) * sd * 0.45)), l: r2(Math.min(o, c) * (1 - Math.abs(gauss()) * sd * 0.45)), c: c });
    p = c;
  }
}
var TF = [{ k: '5m', s: 5, w: 24 }, { k: '15m', s: 15, w: 24 }, { k: '1H', s: 60, w: 21 }, { k: '1D', s: 390, w: 20 }];
var agg = [];
function aggregate() {
  agg = TF.map(function (tf) {
    var out = [], cur = null;
    base.forEach(function (b) {
      var m0 = Math.floor(b.m / tf.s) * tf.s;
      if (!cur || cur.d !== b.d || cur.m0 !== m0) { cur = { d: b.d, m0: m0, o: b.o, h: b.h, l: b.l, c: b.c }; out.push(cur); }
      else { cur.h = Math.max(cur.h, b.h); cur.l = Math.min(cur.l, b.l); cur.c = b.c; }
    });
    var e = out[0].c;
    out.forEach(function (x, i) { e = i ? e + (x.c - e) * 2 / 21 : x.c; x.e = e; });
    return out;
  });
}
function lin(d, m) { return d * 390 + m; }

var sel = 0, ex = false, panels = [];
TF.forEach(function (tf, i) {
  var el = document.createElement('div');
  el.className = 'ccd-mtf-strip-p'; el.setAttribute('role', 'button'); el.setAttribute('tabindex', '-1');
  el.innerHTML = '<div class="ccd-mtf-strip-ph"><b>' + tf.k + '</b><span class="ch"></span><span class="tr"></span></div><svg aria-hidden="true"></svg>';
  el.addEventListener('click', function () { if (sel === i) ex = !ex; else sel = i; paint(); });
  grid.appendChild(el); panels.push(el);
});

function drawPanel(i) {
  var el = panels[i], svg = el.querySelector('svg'), bars = agg[i], tf = TF[i];
  var W = Math.max(110, Math.round(svg.getBoundingClientRect().width) || 170), H = Math.round(svg.getBoundingClientRect().height) || 58;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  var vis = bars.slice(-tf.w), n = vis.length, AX = 34, PW = W - AX, bw = PW / n, cw = Math.max(1.2, Math.min(7, bw * 0.62));
  var hi = -Infinity, lo = Infinity;
  vis.forEach(function (b) { hi = Math.max(hi, b.h, b.e); lo = Math.min(lo, b.l, b.e); });
  var hiR = Math.max.apply(null, vis.map(function (b) { return b.h; })), loR = Math.min.apply(null, vis.map(function (b) { return b.l; }));
  var pad = (hi - lo) * 0.08; hi += pad; lo -= pad;
  function Y(v) { return r1(2 + (hi - v) / (hi - lo) * (H - 4)); }
  var out = '';
  /* shade the span that the next-lower panel is showing */
  if (i > 0) {
    var lw = agg[i - 1].slice(-TF[i - 1].w)[0], t0 = lin(lw.d, lw.m0);
    for (var k = 0; k < n; k++) if (lin(vis[k].d, Math.min(390, vis[k].m0 + tf.s)) > t0) break;
    if (k < n) out += '<rect class="sh" x="' + r1(k * bw) + '" y="0" width="' + r1(PW - k * bw) + '" height="' + H + '"/>';
  }
  var pts = [];
  vis.forEach(function (b, k) {
    var x = r1((k + 0.5) * bw), cl = b.c >= b.o ? 'cu' : 'cd', yo = Y(b.o), yc = Y(b.c);
    out += '<line class="w ' + cl + '" x1="' + x + '" x2="' + x + '" y1="' + Y(b.h) + '" y2="' + Y(b.l) + '"/><rect class="b ' + cl + '" x="' + r1(x - cw / 2) + '" y="' + Math.min(yo, yc) + '" width="' + r1(cw) + '" height="' + Math.max(1, r1(Math.abs(yc - yo))) + '"/>';
    pts.push(x + ',' + Y(b.e));
  });
  out += '<polyline class="em" points="' + pts.join(' ') + '"/>';
  var L = vis[n - 1], ly = Y(L.c);
  out += '<line class="sep" x1="' + PW + '" x2="' + PW + '" y1="0" y2="' + H + '"/><line class="lp" x1="0" x2="' + PW + '" y1="' + ly + '" y2="' + ly + '"/>';
  if (Math.abs(Y(hiR) - ly) > 10) out += '<text class="ax" x="' + (PW + 3) + '" y="' + (Y(hiR) + 3) + '">' + f2(hiR) + '</text>';
  if (Math.abs(Y(loR) - ly) > 10) out += '<text class="ax" x="' + (PW + 3) + '" y="' + (Y(loR) + 3) + '">' + f2(loR) + '</text>';
  out += '<rect class="lr" x="' + (PW + 1) + '" y="' + (ly - 5.5) + '" width="' + (AX - 1) + '" height="11" rx="2"/><text class="lt" x="' + (PW + 3) + '" y="' + (ly + 2.5) + '">' + f2(L.c) + '</text>';
  svg.innerHTML = out;
  var chg = L.c / vis[0].o - 1, above = L.c >= L.e;
  var ch = el.querySelector('.ch'); ch.textContent = sg(chg * 100, 2) + '%'; ch.className = 'ch ' + (chg >= 0 ? 'up' : 'dn');
  var tr = el.querySelector('.tr'); tr.textContent = (above ? '▲ >' : '▼ <') + 'EMA20' + (W >= 175 ? ' ' + f2(L.e) : ''); tr.className = 'tr ' + (above ? 'up' : 'dn');
  el.classList.toggle('on', i === sel);
  el.setAttribute('aria-label', tf.k + ' panel, last ' + f2(L.c) + ', ' + (above ? 'above' : 'below') + ' EMA20');
  return above;
}
function paint() {
  aggregate();
  grid.classList.toggle('ex', ex);
  var ab = TF.map(function (tf, i) { return drawPanel(i); });
  var nUp = ab.filter(Boolean).length;
  sum.innerHTML = '<span>Alignment</span>' + TF.map(function (tf, i) { return '<b class="' + (ab[i] ? 'up' : 'dn') + '">' + tf.k + (ab[i] ? '▲' : '▼') + '</b>'; }).join('') +
    '<span>' + nUp + '/4 above EMA20</span><span class="v ' + (nUp === 4 ? 'up' : nUp === 0 ? 'dn' : '') + '">' + (nUp === 4 ? 'ALIGNED BULL' : nUp === 0 ? 'ALIGNED BEAR' : 'MIXED') + '</span>';
  var D = agg[3], last = D[D.length - 1].c, prev = D[D.length - 2].c, dd = last - prev, up = dd >= 0;
  pxEl.textContent = f2(last);
  chgEl.textContent = (up ? '▲ ' : '▼ ') + sg(dd, 2) + ' (' + sg(dd / prev * 100, 2) + '%)';
  chgEl.className = 'ccd-mtf-strip-chg ' + (up ? 'up' : 'dn');
  var lb = base[base.length - 1];
  clk.textContent = 'Wed 23 Sep · 5m bar ' + hm(lb.m) + ' ET' + (closed ? ' · closed' : ' · forming');
}
paint();

root.addEventListener('keydown', function (e) {
  var k = e.key;
  if (k === 'ArrowRight') sel = (sel + 1) % 4;
  else if (k === 'ArrowLeft') sel = (sel + 3) % 4;
  else if (k === 'ArrowDown') sel = (sel + 2) % 4;
  else if (k === 'ArrowUp') sel = (sel + 2) % 4;
  else if (k === 'Enter' || k === ' ') ex = !ex;
  else if (k === 'Escape') ex = false;
  else return;
  e.preventDefault(); paint();
});

/* live ticks move the one shared last price; a new 5m bar opens every 20 ticks until the 16:00 close */
var ticks = 0, closed = false, lastPx = base[base.length - 1].c;
var timer = setInterval(function () {
  if (!root.isConnected) return clearInterval(timer);
  if (closed) return clearInterval(timer);
  var b = base[base.length - 1];
  var step = (rnd() < 0.5 ? -1 : 1) * (1 + Math.floor(rnd() * 5)) / 100;
  b.c = r2(b.c + step); b.h = Math.max(b.h, b.c); b.l = Math.min(b.l, b.c);
  if (++ticks % 20 === 0) { if (b.m < 385) base.push({ d: b.d, m: b.m + 5, o: b.c, h: b.c, l: b.c, c: b.c }); else closed = true; }
  paint();
  pxEl.classList.remove('fu', 'fd'); void pxEl.offsetWidth; pxEl.classList.add(b.c >= lastPx ? 'fu' : 'fd'); lastPx = b.c;
}, 1500);
if (window.ResizeObserver) {
  var lastW = 0, ro = new ResizeObserver(function (en) {
    if (!root.isConnected) return ro.disconnect();
    var w = Math.round(en[0].contentRect.width); if (w !== lastW) { lastW = w; paint(); }
  });
  ro.observe(grid);
}

