var $ = function (s) { return root.querySelector(s); };
var svg = $('.ccd-session-bands-svg'), tbody = $('.ccd-session-bands-tbl tbody'), brEl = $('.ccd-session-bands-br');
var pxEl = $('.ccd-session-bands-px'), chgEl = $('.ccd-session-bands-chg');
var seed = 4394;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 0, v = 0; while (!u) u = rnd(); while (!v) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }
function r5(v) { return Math.round(v * 1e5) / 1e5; }
function r1(v) { return Math.round(v * 10) / 10; }
function f5(v) { return v.toFixed(5); }
function pips(v) { return Math.round(v * 1e5) / 10; }
function sp(v) { return (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(1); }
function hh(lin) { return String(((22 * 60 + lin) % 1440) / 60 | 0).padStart(2, '0'); }
function hm(lin) { var t = (22 * 60 + lin) % 1440; return String(t / 60 | 0).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0'); }

/* 48 half-hour bars from the 22:00 UTC roll; lin = minutes since the roll. Activity follows the FX clock. */
function act(h) {
  if (h >= 22 || h < 0) return 2.4; if (h < 1) return 3.6; if (h < 6) return 3; if (h < 7) return 4.4; if (h < 9) return 8.8;
  if (h < 12) return 6; if (h < 12.5) return 7.5; if (h < 13) return 12; if (h < 16) return 8.4; if (h < 17) return 5; if (h < 21) return 3.4; return 2.2;
}
var bars = [], p = 1.17158;
for (var k = 0; k < 48; k++) {
  var lin = k * 30, h = ((22 * 60 + lin) % 1440) / 60, sd = act(h) * 1e-4, dr = h >= 7 && h < 11 ? 1.2e-4 : h >= 13 && h < 15 ? -0.6e-4 : 0.1e-4;
  var o = r5(p), c = r5(o + dr + gauss() * sd);
  bars.push({ lin: lin, o: o, c: c, h: r5(Math.max(o, c) + Math.abs(gauss()) * sd * 0.5), l: r5(Math.min(o, c) - Math.abs(gauss()) * sd * 0.5) });
  p = c;
}
var SES = [
  { k: 'TKY', n: 'Tokyo', a: 120, b: 660, u: '00–09' },
  { k: 'LDN', n: 'London', a: 540, b: 1080, u: '07–16' },
  { k: 'NY', n: 'New York', a: 840, b: 1380, u: '12–21' },
  { k: '24H', n: 'Day', a: 0, b: 1440, u: '22–22' }
];
SES.forEach(function (s) {
  var in_ = bars.filter(function (b) { return b.lin >= s.a && b.lin < s.b; });
  s.o = in_[0].o; s.c = in_[in_.length - 1].c;
  s.h = Math.max.apply(null, in_.map(function (b) { return b.h; })); s.l = Math.min.apply(null, in_.map(function (b) { return b.l; }));
  s.rng = pips(s.h - s.l); s.net = pips(s.c - s.o);
});
/* Asia range break during London */
var AR = SES[0], brk = null;
bars.forEach(function (b) {
  if (brk || b.lin < 540 || b.lin >= 1080) return;
  if (b.h > AR.h) brk = { b: b, up: true }; else if (b.l < AR.l) brk = { b: b, up: false };
});
var ext = brk ? (brk.up ? pips(SES[1].h - AR.h) : pips(AR.l - SES[1].l)) : 0;
brEl.textContent = 'Asia rng ' + AR.rng.toFixed(1) + 'p · ' + (brk ? 'LDN broke ' + (brk.up ? '▲ hi ' : '▼ lo ') + hm(brk.b.lin) + ', ext ' + sp(ext) + 'p' : 'no break');

var sel = null;
function render() {
  var W = Math.max(240, Math.round(svg.getBoundingClientRect().width) || 340), H = 150;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  var AX = 46, PW = W - AX, LT = 0, LH = 9, PT = 3 * LH + 6, PB = H - 13;
  var hi = Math.max.apply(null, bars.map(function (b) { return b.h; })), lo = Math.min.apply(null, bars.map(function (b) { return b.l; }));
  var pad = (hi - lo) * 0.08; hi += pad; lo -= pad;
  function Y(v) { return r1(PT + (hi - v) / (hi - lo) * (PB - PT)); }
  function X(lin) { return r1(lin / 1440 * PW); }
  var bw = PW / 48, cw = Math.max(2, Math.min(7, bw * 0.6)), out = '';
  /* session lanes (a Gantt strip) and translucent bands through the price pane */
  SES.slice(0, 3).forEach(function (s, i) {
    var x = X(s.a), w = X(s.b) - x, on = sel === i ? ' on' : '';
    out += '<rect class="bd s' + i + on + '" x="' + x + '" y="' + PT + '" width="' + w + '" height="' + (PB - PT) + '" stroke="none"/>';
    out += '<rect class="ln s' + i + on + '" data-s="' + i + '" x="' + x + '" y="' + (LT + i * LH) + '" width="' + w + '" height="' + (LH - 1) + '" rx="1.5" stroke="none"/><text class="lnt" x="' + (x + 3) + '" y="' + (LT + i * LH + 6.5) + '">' + s.k + ' ' + s.u + '</text>';
  });
  var st = 0.001;
  for (var v = Math.ceil(lo / st) * st; v <= hi; v += st) {
    var y = Y(v);
    out += '<line class="gr" x1="0" x2="' + PW + '" y1="' + y + '" y2="' + y + '"/><text class="ax" x="' + (PW + 4) + '" y="' + (y + 3) + '">' + v.toFixed(4) + '</text>';
  }
  var hstep = PW / 8 >= 30 ? 3 : 6;
  for (var lin = 120; lin < 1440; lin += 60) {
    var hr = ((22 * 60 + lin) % 1440) / 60;
    if (hr % hstep) continue;
    var tx = X(lin);
    out += '<line class="gr" x1="' + tx + '" x2="' + tx + '" y1="' + PT + '" y2="' + PB + '"/><text class="ax" x="' + tx + '" y="' + (H - 3) + '" text-anchor="middle">' + hh(lin) + '</text>';
  }
  out += '<text class="ax" x="' + (PW + 4) + '" y="' + (H - 3) + '">UTC</text>';
  out += '<line class="sep" x1="' + PW + '" x2="' + PW + '" y1="' + PT + '" y2="' + PB + '"/><line class="sep" x1="0" x2="' + W + '" y1="' + PB + '" y2="' + PB + '"/>';
  /* Asia range carried into London */
  var ax0 = X(AR.a), ax1 = X(1080);
  out += '<line class="ar" x1="' + ax0 + '" x2="' + ax1 + '" y1="' + Y(AR.h) + '" y2="' + Y(AR.h) + '"/><line class="ar" x1="' + ax0 + '" x2="' + ax1 + '" y1="' + Y(AR.l) + '" y2="' + Y(AR.l) + '"/>';
  out += '<text class="art" x="' + (ax0 + 2) + '" y="' + (Y(AR.h) - 2) + '">AR hi</text><text class="art" x="' + (ax0 + 2) + '" y="' + (Y(AR.l) + 8) + '">AR lo</text>';
  if (sel !== null) {
    var s = SES[sel], cls = sel < 3 ? 's' + sel : '', a = sel < 3 ? X(s.a) : 0, b = sel < 3 ? X(s.b) : PW;
    out += '<line class="sl ' + cls + '" stroke="#A9B4C6" x1="' + a + '" x2="' + b + '" y1="' + Y(s.h) + '" y2="' + Y(s.h) + '"/><line class="sl ' + cls + '" stroke="#A9B4C6" x1="' + a + '" x2="' + b + '" y1="' + Y(s.l) + '" y2="' + Y(s.l) + '"/>';
  }
  bars.forEach(function (bb, i) {
    var x = r1((i + 0.5) * bw), cl = bb.c >= bb.o ? 'cu' : 'cd', yo = Y(bb.o), yc = Y(bb.c);
    out += '<line class="w ' + cl + '" x1="' + x + '" x2="' + x + '" y1="' + Y(bb.h) + '" y2="' + Y(bb.l) + '"/><rect class="b ' + cl + '" x="' + r1(x - cw / 2) + '" y="' + Math.min(yo, yc) + '" width="' + r1(cw) + '" height="' + Math.max(1, r1(Math.abs(yc - yo))) + '"/>';
  });
  if (brk) {
    var bi = bars.indexOf(brk.b), mx = r1((bi + 0.5) * bw), my = brk.up ? Y(brk.b.h) - 5 : Y(brk.b.l) + 5;
    out += '<path class="mk" d="' + (brk.up ? 'M' + (mx - 3.5) + ' ' + my + 'L' + mx + ' ' + (my - 5) + 'L' + (mx + 3.5) + ' ' + my + 'Z' : 'M' + (mx - 3.5) + ' ' + my + 'L' + mx + ' ' + (my + 5) + 'L' + (mx + 3.5) + ' ' + my + 'Z') + '"/>';
    out += '<text class="mkt" x="' + (mx + 5) + '" y="' + (brk.up ? my - 1 : my + 6) + '">' + hm(brk.b.lin) + '</text>';
  }
  var L = bars[47], ly = Y(L.c), lc = L.c >= SES[3].o ? 'cu' : 'cd';
  out += '<line class="lp ' + lc + '" x1="0" x2="' + PW + '" y1="' + ly + '" y2="' + ly + '"/><rect class="' + lc + '" x="' + (PW + 1) + '" y="' + (ly - 6) + '" width="' + (AX - 2) + '" height="12" rx="2"/><text class="tagt" x="' + (PW + 3) + '" y="' + (ly + 3) + '">' + f5(L.c) + '</text>';
  svg.innerHTML = out;
}
function table() {
  tbody.innerHTML = SES.map(function (s, i) {
    return '<tr data-s="' + i + '" class="' + (i === 3 ? 'tot' : '') + (sel === i ? ' on' : '') + '"><td><i class="s' + i + '"></i>' + s.k + '</td><td class="u">' + s.u + '</td><td>' + f5(s.h) + '</td><td>' + f5(s.l) + '</td><td>' + s.rng.toFixed(1) + '</td><td class="' + (s.net >= 0 ? 'up' : 'dn') + '">' + (s.net >= 0 ? '▲' : '▼') + sp(s.net) + '</td></tr>';
  }).join('');
}
function head() {
  var D = SES[3], up = D.net >= 0;
  pxEl.textContent = f5(D.c);
  chgEl.textContent = (up ? '▲ ' : '▼ ') + sp(D.net) + 'p (' + (up ? '+' : '−') + Math.abs((D.c - D.o) / D.o * 100).toFixed(2) + '%) 24h';
  chgEl.className = 'ccd-session-bands-chg ' + (up ? 'up' : 'dn');
}
function setSel(i) { sel = i; render(); table(); }
head(); render(); table();

tbody.addEventListener('pointerover', function (e) { var tr = e.target.closest('tr'); if (tr && +tr.getAttribute('data-s') !== sel) setSel(+tr.getAttribute('data-s')); });
tbody.addEventListener('pointerleave', function () { setSel(null); });
tbody.addEventListener('click', function (e) { var tr = e.target.closest('tr'); if (tr) setSel(+tr.getAttribute('data-s')); });
svg.addEventListener('click', function (e) { var s = e.target.getAttribute && e.target.getAttribute('data-s'); if (s !== null && s !== undefined) setSel(sel === +s ? null : +s); });
root.addEventListener('keydown', function (e) {
  var k = e.key;
  if (k === 'ArrowDown') setSel(sel === null ? 0 : (sel + 1) % 4);
  else if (k === 'ArrowUp') setSel(sel === null ? 3 : (sel + 3) % 4);
  else if (k === 'Escape') setSel(null);
  else return;
  e.preventDefault();
});
if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () { if (!root.isConnected) return ro.disconnect(); render(); });
  ro.observe(svg);
}

