var $ = function (s) { return root.querySelector(s); };
var sc = $('.ccd-pnf-sc'), gS = $('.ccd-pnf-g'), aS = $('.ccd-pnf-ax'), meta = $('.ccd-pnf-meta');
var E = { sig: $('.ccd-pnf-sig'), col: $('.ccd-pnf-col'), nx: $('.ccd-pnf-nx'), rv: $('.ccd-pnf-rv'), px: $('.ccd-pnf-px'), chg: $('.ccd-pnf-chg') };
var seed = 1207;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 0, v = 0; while (!u) u = rnd(); while (!v) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }
function f2(v) { return v.toFixed(2); }
var MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
var MC = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'A', 'B', 'C'];
/* one year of NYSE sessions */
var HOL = {};
'2025-11-27 2025-12-25 2026-01-01 2026-01-19 2026-02-16 2026-04-03 2026-05-25 2026-06-19 2026-07-03 2026-09-07'.split(' ').forEach(function (d) { HOL[d] = 1; });
var dates = [], d0 = new Date(Date.UTC(2026, 8, 23));
while (dates.length < 252) { var w = d0.getUTCDay(); if (w > 0 && w < 6 && !HOL[d0.toISOString().slice(0, 10)]) dates.unshift(new Date(d0.getTime())); d0.setUTCDate(d0.getUTCDate() - 1); }
var closes = [], p = 288.4;
for (var i = 0; i < dates.length; i++) {
  var mu = i < 60 ? 0.0012 : i < 110 ? -0.0016 : i < 190 ? 0.0014 : i < 215 ? -0.0012 : 0.0009;
  if (i) p = p * Math.exp(mu + gauss() * 0.0125);
  closes.push(Math.round(p * 100) / 100);
}
function dl(i) { return dates[i].getUTCDate() + ' ' + MON[dates[i].getUTCMonth()]; }

/* close-only point and figure: box index k stands for price k*box */
function build(box, rev) {
  var cols = [], cur = null, lastM = -1, sigs = [];
  function up(v) { return Math.floor(v / box + 1e-9); }
  function dn(v) { return Math.ceil(v / box - 1e-9); }
  function mark(c, k, i) { var m = dates[i].getUTCMonth(); if (m !== lastM) { c.mk[k] = MC[m]; lastM = m; } }
  function sig(c, edge, i) {
    var pv = cols[cols.length - 3], pp = cols[cols.length - 5];
    if (!pv || c.sg) return;
    if (c.x && edge <= pv.hi && c.hi > pv.hi) c.sg = { buy: true, k: pv.hi + 1, i: i, name: pp && pp.hi === pv.hi ? 'triple top' : 'double top' };
    if (!c.x && edge >= pv.lo && c.lo < pv.lo) c.sg = { buy: false, k: pv.lo - 1, i: i, name: pp && pp.lo === pv.lo ? 'triple bottom' : 'double bottom' };
    if (c.sg) sigs.push(c.sg);
  }
  var base = Math.round(closes[0] / box);
  for (var i = 1; i < closes.length; i++) {
    var v = closes[i], old;
    if (!cur) {
      if (up(v) >= base + 1) { cur = { x: true, lo: base, hi: up(v), mk: {}, i: i }; cols.push(cur); mark(cur, base, i); }
      else if (dn(v) <= base - 1) { cur = { x: false, hi: base, lo: dn(v), mk: {}, i: i }; cols.push(cur); mark(cur, base, i); }
      continue;
    }
    if (cur.x) {
      if (up(v) > cur.hi) { old = cur.hi; cur.hi = up(v); cur.i = i; mark(cur, old + 1, i); sig(cur, old, i); }
      else if (dn(v) <= cur.hi - rev) { cur = { x: false, hi: cur.hi - 1, lo: dn(v), mk: {}, i: i }; cols.push(cur); mark(cur, cur.hi, i); sig(cur, cur.hi + 1, i); }
    } else {
      if (dn(v) < cur.lo) { old = cur.lo; cur.lo = dn(v); cur.i = i; mark(cur, old - 1, i); sig(cur, old, i); }
      else if (up(v) >= cur.lo + rev) { cur = { x: true, lo: cur.lo + 1, hi: up(v), mk: {}, i: i }; cols.push(cur); mark(cur, cur.lo, i); sig(cur, cur.lo - 1, i); }
    }
  }
  return { cols: cols, sigs: sigs };
}

var BOXES = [1, 2, 5], REVS = [1, 2, 3], box = 2, rev = 3, C = 11;
function render() {
  var res = build(box, rev), cols = res.cols, n = cols.length, last = closes[closes.length - 1];
  var kmin = Infinity, kmax = -Infinity;
  cols.forEach(function (c) { kmin = Math.min(kmin, c.lo); kmax = Math.max(kmax, c.hi); });
  kmin -= 2; kmax += 2;
  var rows = kmax - kmin + 1, GW = (n + 2) * C, GH = rows * C, AW = 44;
  function Y(k) { return (kmax - k) * C; }
  gS.setAttribute('width', GW); gS.setAttribute('height', GH); gS.setAttribute('viewBox', '0 0 ' + GW + ' ' + GH);
  aS.setAttribute('width', AW); aS.setAttribute('height', GH); aS.setAttribute('viewBox', '0 0 ' + AW + ' ' + GH);
  var g = '', a = '', k, j;
  for (k = kmin; k <= kmax + 1; k++) g += '<line class="' + ((k * box) % (box * 5) === 0 ? 'gm' : 'gl') + '" x1="0" x2="' + GW + '" y1="' + (Y(k) + C) + '" y2="' + (Y(k) + C) + '"/>';
  for (j = 0; j <= n + 2; j++) g += '<line class="gl" x1="' + j * C + '" x2="' + j * C + '" y1="0" y2="' + GH + '"/>';
  cols.forEach(function (c, j) {
    var x = (j + 1) * C;
    for (var k = c.lo; k <= c.hi; k++) {
      var y = Y(k);
      if (c.mk[k]) g += '<text class="mc" x="' + (x + C / 2) + '" y="' + (y + C / 2 + 3) + '" text-anchor="middle">' + c.mk[k] + '</text>';
      else if (c.x) g += '<path class="x" d="M' + (x + 2.5) + ' ' + (y + 2.5) + 'L' + (x + C - 2.5) + ' ' + (y + C - 2.5) + 'M' + (x + 2.5) + ' ' + (y + C - 2.5) + 'L' + (x + C - 2.5) + ' ' + (y + 2.5) + '"/>';
      else g += '<circle class="o" cx="' + (x + C / 2) + '" cy="' + (y + C / 2) + '" r="' + (C / 2 - 2.2) + '"/>';
    }
    if (c.sg) {
      var sy = Y(c.sg.k);
      g += '<rect class="' + (c.sg.buy ? 'sb' : 'ss') + '" x="' + (x + 0.5) + '" y="' + (sy + 0.5) + '" width="' + (C - 1) + '" height="' + (C - 1) + '"/>';
      g += '<text class="sgt ' + (c.sg.buy ? 'b' : 's') + '" x="' + (x + C / 2) + '" y="' + (c.sg.buy ? Y(c.hi) - 2 : Y(c.lo) + C + 6) + '" text-anchor="middle">' + (c.sg.buy ? 'B' : 'S') + '</text>';
    }
  });
  var cur = cols[n - 1], ck = cur.x ? cur.hi : cur.lo, cx = n * C, cy = Y(ck);
  g += '<rect class="cur" x="' + (cx + 0.5) + '" y="' + (cy + 0.5) + '" width="' + (C - 1) + '" height="' + (C - 1) + '"/>';
  var ly = (kmax - last / box) * C + C / 2;
  g += '<line class="cp" x1="' + (cx + C) + '" x2="' + GW + '" y1="' + ly + '" y2="' + ly + '"/>';
  for (k = kmin; k <= kmax; k++) {
    var major = (k * box) % (box * 5) === 0;
    a += '<text class="al' + (major ? ' m' : '') + '" x="4" y="' + (Y(k) + C / 2 + 3) + '">' + (k * box).toFixed(box < 1 ? 2 : 0) + '</text>';
  }
  a += '<path class="tg" d="M0 ' + ly + 'L5 ' + (ly - 6) + 'H' + AW + 'V' + (ly + 6) + 'H5Z"/><text class="tgt" x="6" y="' + (ly + 3) + '">' + f2(last) + '</text>';
  gS.innerHTML = g; aS.innerHTML = a;
  /* readouts */
  var s = res.sigs[res.sigs.length - 1];
  E.sig.innerHTML = s ? '<span class="' + (s.buy ? 'up' : 'dn') + '">' + (s.buy ? '▲ BUY' : '▼ SELL') + '</span> ' + s.name + ' @ ' + f2(s.k * box) + ' · ' + dl(s.i) : 'none';
  E.col.textContent = '#' + n + ' ' + (cur.x ? 'X ' + f2(cur.lo * box) + '→' + f2(cur.hi * box) : 'O ' + f2(cur.hi * box) + '→' + f2(cur.lo * box)) + ' (' + (cur.hi - cur.lo + 1) + ' boxes)';
  E.nx.innerHTML = cur.x ? '<span class="up">X</span> on close ≥ ' + f2((cur.hi + 1) * box) : '<span class="dn">O</span> on close ≤ ' + f2((cur.lo - 1) * box);
  E.rv.innerHTML = cur.x ? '<span class="dn">O</span> on close ≤ ' + f2((cur.hi - rev) * box) : '<span class="up">X</span> on close ≥ ' + f2((cur.lo + rev) * box);
  meta.textContent = n + ' cols · ' + box + '×' + rev + ' · ' + res.sigs.length + ' signals';
  root.querySelectorAll('.ccd-pnf-seg').forEach(function (sg) {
    var v = sg.getAttribute('data-g') === 'box' ? box : rev;
    sg.querySelectorAll('button').forEach(function (b) { b.setAttribute('aria-pressed', +b.getAttribute('data-v') === v ? 'true' : 'false'); });
  });
  sc.scrollLeft = sc.scrollWidth;
  sc.scrollTop = Math.max(0, cy - sc.clientHeight / 2);
}
function head() {
  var L = closes[closes.length - 1], P = closes[closes.length - 2], d = L - P, up = d >= 0;
  E.px.textContent = f2(L);
  E.chg.textContent = (up ? '▲ +' : '▼ −') + f2(Math.abs(d)) + ' (' + (up ? '+' : '−') + Math.abs(d / P * 100).toFixed(2) + '%)';
  E.chg.className = 'ccd-pnf-chg ' + (up ? 'up' : 'dn');
}
head(); render();

root.querySelectorAll('.ccd-pnf-seg button').forEach(function (b) {
  b.addEventListener('click', function () {
    var v = +b.getAttribute('data-v');
    if (b.parentNode.getAttribute('data-g') === 'box') box = v; else rev = v;
    render();
  });
});
root.addEventListener('keydown', function (e) {
  var k = e.key;
  if (k === 'b' || k === 'B') { box = BOXES[(BOXES.indexOf(box) + 1) % BOXES.length]; render(); }
  else if (k === 'r' || k === 'R') { rev = REVS[(REVS.indexOf(rev) + 1) % REVS.length]; render(); }
  else if (k === 'ArrowLeft') sc.scrollLeft -= C * 3;
  else if (k === 'ArrowRight') sc.scrollLeft += C * 3;
  else if (k === 'ArrowUp') sc.scrollTop -= C * 3;
  else if (k === 'ArrowDown') sc.scrollTop += C * 3;
  else if (k === 'Home') sc.scrollLeft = 0;
  else if (k === 'End') render();
  else return;
  e.preventDefault();
});
/* re-anchor on the latest box if the panel mounted hidden or changed width */
if (window.ResizeObserver) {
  var lastW = sc.clientWidth, ro = new ResizeObserver(function () {
    if (!root.isConnected) return ro.disconnect();
    if (sc.clientWidth && sc.clientWidth !== lastW) { lastW = sc.clientWidth; render(); }
  });
  ro.observe(sc);
}
